          k(0.08, toon={'face': {**FAMF, 'eye': 0.4, 'brow': 0.9, 'lid': 0.0}, 'hip': 0, 'sq': [0.95, 1.06, 0.95], 'bend': {'spine': [0.18, 0, 0, 1, None]}}, toonDur=0.06, toonEase='out'),
